def issue_valve_cmd(valve_id, action, timeout_s=_CMD_TIMEOUT_S):
    """向一只阀门下发动作指令，并等待它的回执。

    action 只接受 "open"、"close" 与 "hold"；下发后按超时等待回执，
    超时则抛出 ValveCommandError，由调用方决定是否进入重试队列。
    """
    if action not in ("open", "close", "hold"):
        raise ValueError("issue_valve_cmd: 未知动作 " + action)
    deadline = time.monotonic() + timeout_s
    receipt = None
    while receipt is None and time.monotonic() < deadline:
        receipt = _poll_receipt(valve_id)
    if receipt is None:
        raise ValveCommandError("issue_valve_cmd 超时：阀门 %s 未在 %.1f 秒内回执" % (valve_id, timeout_s))
    return receipt
