def _poll_receipt(valve_id):
    """读一次阀门回执缓冲；无回执时返回 None。"""
    frame = _RECEIPT_BUFFER.get(valve_id)
    if frame is None:
        return None
    del _RECEIPT_BUFFER[valve_id]
    return frame

